import { serve } from "https://deno.land/std@0.190.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.50.0";
import { disabledHostawayResponse, isHostawayIntegrationEnabled } from '../_shared/disabledIntegration.ts';

const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;

const supabase = createClient(supabaseUrl, supabaseServiceKey);

// Configuración Hostaway
const HOSTAWAY_ACCOUNT_ID = 80687;
const HOSTAWAY_API_BASE = 'https://api.hostaway.com/v1';

interface HostawayProperty {
  id: number;
  internalName: string;
  listingMapId: number;
  address?: string;
  city?: string;
}

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

async function getHostawayToken(): Promise<string> {
  console.log('Obteniendo token de Hostaway...');
  
  const clientId = Deno.env.get('HOSTAWAY_CLIENT_ID');
  const clientSecret = Deno.env.get('HOSTAWAY_CLIENT_SECRET');
  
  if (!clientId || !clientSecret) {
    throw new Error('Credenciales de Hostaway no configuradas');
  }

  const response = await fetch(`${HOSTAWAY_API_BASE}/accessTokens`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: new URLSearchParams({
      grant_type: 'client_credentials',
      client_id: clientId,
      client_secret: clientSecret,
      scope: 'general',
    }),
  });

  if (!response.ok) {
    throw new Error(`Error obteniendo token: ${response.statusText}`);
  }

  const data = await response.json();
  return data.access_token;
}

async function fetchHostawayProperties(token: string): Promise<HostawayProperty[]> {
  console.log('Obteniendo propiedades de Hostaway...');
  
  const url = new URL(`${HOSTAWAY_API_BASE}/listings`);
  url.searchParams.append('accountId', HOSTAWAY_ACCOUNT_ID.toString());
  url.searchParams.append('limit', '100');

  const response = await fetch(url.toString(), {
    headers: {
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
  });

  if (!response.ok) {
    throw new Error(`Error obteniendo propiedades: ${response.statusText}`);
  }

  const data = await response.json();
  console.log(`Propiedades obtenidas de Hostaway: ${data.result?.length || 0}`);
  return data.result || [];
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  if (!isHostawayIntegrationEnabled()) {
    return disabledHostawayResponse(corsHeaders);
  }

  try {
    console.log('Iniciando inserción de propiedades desde Hostaway...');

    // Verificar si ya existe el cliente Blue Ocean Properties
    let { data: existingClient } = await supabase
      .from('clients')
      .select('*')
      .eq('nombre', 'Blue Ocean Properties')
      .single();

    let clientId: string;

    if (!existingClient) {
      console.log('Creando cliente Blue Ocean Properties...');
      const { data: newClient, error: clientError } = await supabase
        .from('clients')
        .insert({
          nombre: 'Blue Ocean Properties',
          email: 'info@blueoceanproperties.com',
          telefono: '+34900000000',
          direccion_facturacion: 'Calle Principal, 123, Madrid',
          cif_nif: 'B12345678',
          tipo_servicio: 'limpieza-turistica',
          metodo_pago: 'transferencia',
          supervisor: 'Administrador',
          factura: true,
          ciudad: 'Madrid',
          codigo_postal: '28001'
        })
        .select()
        .single();

      if (clientError) {
        console.error('Error creando cliente:', clientError);
        throw clientError;
      }

      clientId = newClient.id;
      console.log('Cliente creado con ID:', clientId);
    } else {
      clientId = existingClient.id;
      console.log('Cliente existente encontrado con ID:', clientId);
    }

    // Obtener propiedades de Hostaway
    const token = await getHostawayToken();
    const hostawayProperties = await fetchHostawayProperties(token);
    
    console.log(`Obtenidas ${hostawayProperties.length} propiedades de Hostaway`);

    // Primero obtener todas las propiedades existentes
    const { data: existingProperties, error: fetchError } = await supabase
      .from('properties')
      .select('*');

    if (fetchError) {
      console.error('Error obteniendo propiedades existentes:', fetchError);
      throw fetchError;
    }

    console.log(`Propiedades existentes en la base de datos: ${existingProperties?.length || 0}`);

    let insertedCount = 0;
    let updatedCount = 0;
    let errorCount = 0;

    for (const property of hostawayProperties) {
      try {
        console.log(`Procesando propiedad: ${property.internalName} (listingMapId: ${property.listingMapId})`);

        // Buscar si la propiedad ya existe por hostaway_listing_id
        const existingProperty = existingProperties?.find(p => p.hostaway_listing_id === property.listingMapId);

        const propertyData = {
          cliente_id: clientId,
          nombre: property.internalName || `Propiedad ${property.listingMapId}`,
          codigo: `HOST_${property.listingMapId}`,
          direccion: property.address || `Dirección de ${property.internalName}`,
          numero_camas: 1,
          numero_banos: 1,
          numero_sabanas: 2,
          numero_fundas_almohada: 2,
          numero_toallas_pequenas: 2,
          numero_toallas_grandes: 2,
          numero_alfombrines: 1,
          duracion_servicio: 60,
          coste_servicio: 50.00,
          check_in_predeterminado: '15:00:00',
          check_out_predeterminado: '11:00:00',
          hostaway_listing_id: property.listingMapId,
          hostaway_internal_name: property.internalName,
          notas: `Propiedad importada de Hostaway. Listing Map ID: ${property.listingMapId}`
        };

        if (existingProperty) {
          // Actualizar propiedad existente
          console.log(`Actualizando propiedad existente: ${existingProperty.id}`);
          const { error: updateError } = await supabase
            .from('properties')
            .update(propertyData)
            .eq('id', existingProperty.id);

          if (updateError) {
            console.error(`Error actualizando propiedad ${property.listingMapId}:`, updateError);
            errorCount++;
          } else {
            console.log(`✅ Propiedad actualizada: ${property.internalName} (ID: ${property.listingMapId})`);
            updatedCount++;
          }
        } else {
          // Buscar si existe una propiedad que coincida por nombre pero sin hostaway_listing_id
          const similarProperty = existingProperties?.find(p => 
            !p.hostaway_listing_id && (
              p.nombre.toLowerCase().includes(property.internalName?.toLowerCase() || '') ||
              property.internalName?.toLowerCase().includes(p.nombre.toLowerCase())
            )
          );

          if (similarProperty) {
            // Actualizar la propiedad similar con el hostaway_listing_id
            console.log(`Actualizando propiedad similar: ${similarProperty.nombre} -> ${property.internalName}`);
            const { error: updateError } = await supabase
              .from('properties')
              .update({
                ...propertyData,
                fecha_actualizacion: new Date().toISOString().split('T')[0]
              })
              .eq('id', similarProperty.id);

            if (updateError) {
              console.error(`Error actualizando propiedad similar ${property.listingMapId}:`, updateError);
              errorCount++;
            } else {
              console.log(`✅ Propiedad similar actualizada: ${property.internalName} (ID: ${property.listingMapId})`);
              updatedCount++;
            }
          } else {
            // Insertar nueva propiedad
            console.log(`Insertando nueva propiedad: ${property.internalName}`);
            const { error: insertError } = await supabase
              .from('properties')
              .insert(propertyData);

            if (insertError) {
              console.error(`Error insertando propiedad ${property.listingMapId}:`, insertError);
              errorCount++;
            } else {
              console.log(`✅ Propiedad insertada: ${property.internalName} (ID: ${property.listingMapId})`);
              insertedCount++;
            }
          }
        }
      } catch (error) {
        console.error(`Error procesando propiedad ${property.listingMapId}:`, error);
        errorCount++;
      }
    }

    // Verificar cuántas propiedades tienen hostaway_listing_id después del proceso
    const { data: updatedPropertiesCheck } = await supabase
      .from('properties')
      .select('hostaway_listing_id')
      .not('hostaway_listing_id', 'is', null);

    console.log(`Propiedades con hostaway_listing_id después del proceso: ${updatedPropertiesCheck?.length || 0}`);

    const summary = {
      success: true,
      message: `Proceso completado: ${insertedCount} propiedades insertadas, ${updatedCount} actualizadas, ${errorCount} errores`,
      details: {
        total_properties: hostawayProperties.length,
        inserted: insertedCount,
        updated: updatedCount,
        errors: errorCount,
        client_id: clientId,
        properties_with_hostaway_id: updatedPropertiesCheck?.length || 0
      }
    };

    console.log('Resumen final:', summary);

    return new Response(JSON.stringify(summary), {
      status: 200,
      headers: {
        'Content-Type': 'application/json',
        ...corsHeaders,
      },
    });

  } catch (error) {
    console.error('Error en inserción de propiedades:', error);
    
    return new Response(JSON.stringify({ 
      error: error.message,
      success: false 
    }), {
      status: 500,
      headers: {
        'Content-Type': 'application/json',
        ...corsHeaders,
      },
    });
  }
});

export const HOSTAWAY_INTEGRATION_DISABLED = 'HOSTAWAY_INTEGRATION_DISABLED';

export function isHostawayIntegrationEnabled(): boolean {
  return false;
}

export function disabledHostawayResponse(corsHeaders: Record<string, string>): Response {
  return new Response(
    JSON.stringify({
      success: false,
      code: HOSTAWAY_INTEGRATION_DISABLED,
      error: 'La integración con Hostaway está desactivada y conservada para futuros clientes.',
    }),
    {
      status: 410,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    },
  );
}
